import{_ as r,o as t,c as l,a2 as o}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"表层设定","description":"","frontmatter":{},"headers":[],"relativePath":"表层/index.md","filePath":"表层/index.md","lastUpdated":null}'),e={name:"表层/index.md"};function i(n,a,s,h,u,d){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="表层设定" tabindex="-1">表层设定 <a class="header-anchor" href="#表层设定" aria-label="Permalink to &quot;表层设定&quot;">​</a></h1><h2 id="三层结构" tabindex="-1">三层结构 <a class="header-anchor" href="#三层结构" aria-label="Permalink to &quot;三层结构&quot;">​</a></h2><p>神造物世界观分为三个认知层面：<strong>表层设定、中层设定和底层设定</strong>。</p><ul><li><strong>表层设定</strong>：福瑞种族可直接认知的表象世界，包括种族、地理环境与表层历史。</li><li><strong>中层设定</strong>：揭示世界表象背后的真相、技术内涵与深层关联。</li><li><strong>底层设定</strong>：世界观最底层的核心逻辑，包括神权体系、基底层与现实世界的关系。</li></ul><blockquote><p>详见：<a href="./../中层/" class="layer-link" data-layer="中层">中层设定</a>、<a href="./../底层/" class="layer-link" data-layer="底层">底层设定</a>。全站链接带层级徽标（[表层]/[中层]/[底层]），随时可以下潜或返回。</p></blockquote><h2 id="概念诠释" tabindex="-1">概念诠释 <a class="header-anchor" href="#概念诠释" aria-label="Permalink to &quot;概念诠释&quot;">​</a></h2><p>表层设定是神造物世界观中的<strong>表面认知层面</strong>，也是福瑞种族所认知的世界。这一层面包含大陆上各智慧生灵所能接触和理解的直接现实。</p><p>表层是整个世界观叙事的&quot;正门&quot;——读者首先接触的就是这一层面。但这并不意味着表层的设定是虚假的；阳光、友谊与冒险都是真实、确切的。只是在它们之下，还藏着更多的东西。</p><h2 id="定位与特点" tabindex="-1">定位与特点 <a class="header-anchor" href="#定位与特点" aria-label="Permalink to &quot;定位与特点&quot;">​</a></h2><p><strong>核心定位：</strong></p><ul><li><strong>叙事的正面</strong>：作品初期呈现的经典福瑞奇幻冒险世界</li><li><strong>真实的一部分</strong>：表层的美好并非伪装，而是这个世界真实的一部分</li><li><strong>剥洋葱的起始层</strong>：从表层开始，逐渐向深层发掘</li></ul><p><strong>主要特点：</strong></p><ul><li><strong>直观可感</strong>：福瑞种族可直接感知、接触、理解的事物</li><li><strong>可记录</strong>：表层历史、地理、种族特征均可被大陆生灵记录和传承</li><li><strong>带有多重解释</strong>：同一现象在更深的层面可能有完全不同的解释</li></ul><h2 id="主要内容领域" tabindex="-1">主要内容领域 <a class="header-anchor" href="#主要内容领域" aria-label="Permalink to &quot;主要内容领域&quot;">​</a></h2><h3 id="_1-种族设定" tabindex="-1">1. 种族设定 <a class="header-anchor" href="#_1-种族设定" aria-label="Permalink to &quot;1. 种族设定&quot;">​</a></h3><p>包括各福瑞种族的生理特征、种族特质、历史地位与当代现状。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./种族/">种族设定</a></p></blockquote><h3 id="_2-地理环境" tabindex="-1">2. 地理环境 <a class="header-anchor" href="#_2-地理环境" aria-label="Permalink to &quot;2. 地理环境&quot;">​</a></h3><p>大陆的自然环境、生态特点以及遍布各地的古代遗迹。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./地理/">地理环境</a></p></blockquote><h3 id="_3-表层历史" tabindex="-1">3. 表层历史 <a class="header-anchor" href="#_3-表层历史" aria-label="Permalink to &quot;3. 表层历史&quot;">​</a></h3><p>福瑞种族所经历的历史事件记录，从共同体时期到当前时代。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./历史/">表层历史</a></p></blockquote><h3 id="_4-众生录-表层人物" tabindex="-1">4. 众生录（表层人物） <a class="header-anchor" href="#_4-众生录-表层人物" aria-label="Permalink to &quot;4. 众生录（表层人物）&quot;">​</a></h3><p>从表层视角认识这个世界的人物——红星孤儿院的院长与孩子们、传说中的龙王、鹿族高层，以及他们公开可见的一面。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./人物/">众生录</a></p></blockquote><h2 id="与世界观其他层面的关系" tabindex="-1">与世界观其他层面的关系 <a class="header-anchor" href="#与世界观其他层面的关系" aria-label="Permalink to &quot;与世界观其他层面的关系&quot;">​</a></h2><h3 id="与中层设定的关系" tabindex="-1">与中层设定的关系 <a class="header-anchor" href="#与中层设定的关系" aria-label="Permalink to &quot;与中层设定的关系&quot;">​</a></h3><ul><li><strong>表象与真相</strong>：中层设定揭示表层现象背后的真正原因与机制</li><li><strong>认知局限</strong>：福瑞种族无法直接认知中层设定的内容</li></ul><h3 id="与底层设定的关系" tabindex="-1">与底层设定的关系 <a class="header-anchor" href="#与底层设定的关系" aria-label="Permalink to &quot;与底层设定的关系&quot;">​</a></h3><ul><li><strong>现象与本质</strong>：底层是世界的规则层面，表层是这些规则的具体表现</li><li><strong>规则影响</strong>：底层规则无声地塑造着表层世界，其具体机制属于更深层的设定</li></ul><h2 id="阅读建议" tabindex="-1">阅读建议 <a class="header-anchor" href="#阅读建议" aria-label="Permalink to &quot;阅读建议&quot;">​</a></h2><ol><li><strong>从这里开始</strong>：表层设定是了解神造物世界观的最佳起点，建议按「种族总览 → 表层历史 → 种族设定 → 地理环境 → 众生录」的顺序一路读下去（先读历史，各族档案中反复出现的黑暗时代、共同体才有上下文）</li><li><strong>注意伏笔</strong>：表层设定中暗含诸多指向更深层设定的伏笔与线索</li><li><strong>保留&quot;表层视角&quot;</strong>：阅读时尽量保持故事中普通生灵的认知视角</li><li><strong>带着疑问下潜</strong>：读完表层后，你或许会对&quot;地脉是什么&quot;&quot;神明从哪里来&quot;&quot;龙族为何消失&quot;充满疑问——这些答案在中层设定与底层设定中，跟着徽标走即可</li></ol><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./种族总览">种族总览</a></li><li><a href="./种族/">种族设定</a></li><li><a href="./地理/">地理环境</a></li><li><a href="./历史/">表层历史</a></li><li><a href="./人物/">众生录</a></li><li><a href="./../中层/" class="layer-link" data-layer="中层">中层设定</a></li><li><a href="./../底层/" class="layer-link" data-layer="底层">底层设定</a></li><li><a href="./../术语表与索引指南">术语表与索引指南</a></li></ul><hr>',37)])])}const q=r(e,[["render",i]]);export{g as __pageData,q as default};
